protected void new()
{
    if (!AVAWhsSplitWorkProcessIDisposable::current())
    {
        instance = this;
    }
    else
    {
        instance = AVAWhsSplitWorkProcessIDisposable::current();
    }
}

/// <summary>
/// AVA_6726_8001_RFFull_WorkLockMode
